<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$pageTitle='Reports';$basePath='../';$rows=$pdo->query('SELECT l.id,m.member_code,m.name member,b.title,l.quantity,l.issue_date,l.due_date,l.return_date,l.status FROM loans l JOIN members m ON m.id=l.member_id JOIN books b ON b.id=l.book_id ORDER BY l.id DESC')->fetchAll();if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv');header('Content-Disposition: attachment; filename="library-loans.csv"');$out=fopen('php://output','w');fputcsv($out,['Loan ID','Member ID','Member','Book','Quantity','Issue date','Due date','Return date','Status']);foreach($rows as $r)fputcsv($out,$r);fclose($out);exit;}require __DIR__.'/../includes/layout_top.php';?><div class="panel"><div class="panel-head"><div><h3>Circulation report</h3><p>Complete loan history for the library.</p></div><a class="btn primary" href="?export=csv">Export CSV</a></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Member</th><th>Book</th><th>Issue</th><th>Due</th><th>Returned</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=e($r['member'])?><small><?=e($r['member_code'])?></small></td><td><?=e($r['title'])?></td><td><?=e($r['issue_date'])?></td><td><?=e($r['due_date'])?></td><td><?=e($r['return_date']??'—')?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../includes/layout_bottom.php';?>
